CREATE TABLE IF NOT EXISTS communities (id TEXT PRIMARY KEY, place_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS listings (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, community_id TEXT NOT NULL REFERENCES communities(id), title TEXT NOT NULL, location_label TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>=0), type TEXT NOT NULL CHECK(type IN ('rent','sale','service','tenant')), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending_payment','published','expired','removed')), payment_reference TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TEXT);
CREATE INDEX IF NOT EXISTS idx_listing_feed ON listings(status,community_id,created_at);
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, identity_subject TEXT NOT NULL UNIQUE, referral_code TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, listing_id TEXT, agent_id TEXT, amount_kobo INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS commission_ledger (id TEXT PRIMARY KEY, payment_id TEXT NOT NULL UNIQUE, agent_id TEXT NOT NULL, amount_kobo INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
